const normalizedOffers = [];

// Ajout de la plage \u{1F1E6}-\u{1F1FF} spécifique aux drapeaux (Regional Indicator Symbols)
const emojiRegex = /\p{Extended_Pictographic}|[\u{1F1E6}-\u{1F1FF}\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{1FA00}-\u{1FAFF}\u{2B00}-\u{2BFF}\u{2300}-\u{23FF}]/gu;

for (const item of $input.all()) {
    const offer = item.json;

    // Nettoyage des emojis et drapeaux sur le titre
    let title = offer.title || offer.name || "Titre inconnu";
    title = title.replace(emojiRegex, '').trim();

    let description = offer.description || "";

    // Nettoyage des emojis et drapeaux sur la description
    description = description.replace(emojiRegex, '');

    description = description
        .replace(/<[^>]*>/g, ' ')
        .replace(/\*\*/g, '')
        .replace(/__/g, '')
        .replace(/[ \t]+/g, ' ')
        .replace(/\* /g, '- ')
        .trim();

    let contractType = "NC";
    if (offer.post_type) {
        if (offer.post_type.includes('permanent')) contractType = 'CDI';
        else if (offer.post_type.includes('freelance')) contractType = 'Freelance';
        else if (offer.post_type.includes('internship')) contractType = 'Stage';
        else if (offer.post_type.includes('apprenticeship')) contractType = 'Alternance';
        else if (offer.post_type.includes('partTime')) contractType = 'Temps partiel';
        else if (offer.post_type.includes('fixedTerm')) contractType = 'CDD';
        else contractType = offer.post_type.replace(/\[|\]|"/g, '');
    }

    if (contractType === 'NC' && (description.toLowerCase().includes('cdd') || description.toLowerCase().includes('contrat à durée déterminée'))) {
        contractType = 'CDD';
    }

    let city = null;
    let country = null;
    if (offer.location && offer.location.length > 0) {
        const locParts = offer.location[0].split(',');
        if (locParts.length > 1) {
            city = locParts[0].trim();
            country = locParts[1].trim();
        } else {
            country = locParts[0].trim();
        }
    }

    const textToSearch = `${title} ${description}`.toLowerCase();

    const isRemote = textToSearch.includes('remote') || 
                     textToSearch.includes('télétravail') ||
                     textToSearch.includes('home office');

    const isHybrid = textToSearch.includes('hybride') ||
                     textToSearch.includes('hybrid');

    let salaryMin = null;
    let salaryMax = null;
    let currency = "EUR";

    const patterns = [
        { regex: /(\d{2,3})\s*[\/-]\s*(\d{2,3})\s*k/i, multiplier: 1000 },
        { regex: /(\d{2,3})\s*k\s*€?\s*(?:et|à)\s*(\d{2,3})\s*k/i, multiplier: 1000 },
        { regex: /(?:€|K)?\s*(\d{2,3})[\s,.]?000\s*(?:-|à)\s*(?:€|K)?\s*(\d{2,3})[\s,.]?000/i, multiplier: 1 },
        { regex: /(\d{2,3})\s*k\s*€/i, multiplier: 1000 }
    ];

    for (const p of patterns) {
        const match = textToSearch.match(p.regex);
        if (match) {
            salaryMin = parseInt(match[1], 10) * p.multiplier;
            salaryMax = match[2] ? parseInt(match[2], 10) * p.multiplier : salaryMin;
            break;
        }
    }

    if (salaryMin !== null && salaryMin < 1000) {
        salaryMin = salaryMin * 1000;
    }
    if (salaryMax !== null && salaryMax < 1000) {
        salaryMax = salaryMax * 1000;
    }

    if (textToSearch.includes('$') || textToSearch.includes('dollar')) {
        currency = "USD";
    }

    const publishRaw = offer.publish_date || offer.published_at || null;
    let publishDate = null;

    if (publishRaw) {
        const dateInMs = Math.floor(publishRaw / 1000);
        const dateObj = new Date(dateInMs);
        publishDate = dateObj.toISOString().slice(0, 19).replace('T', ' ');
    }

    // Récupération de l'entreprise (gestion de plusieurs formats possibles)
    const company = offer.company_name || (offer.company && offer.company.name) || (typeof offer.company === 'string' ? offer.company : null);

    const rawString = `${title}-${city}-${contractType}-${company}-${publishDate}`.toLowerCase();
    let contentHash = 0;
    for (let i = 0; i < rawString.length; i++) {
        const char = rawString.charCodeAt(i);
        contentHash = ((contentHash << 5) - contentHash) + char;
        contentHash = contentHash & contentHash; 
    }
    const finalHash = Math.abs(contentHash).toString(16);

    normalizedOffers.push({
        json: {
            source: "welovedevs",
            source_id: offer.url || finalHash,
            company: company,
            title: title,
            description: description,
            city: city,
            country: country,
            remote: isRemote,
            hybrid: isHybrid,
            contract_type: contractType,
            salary_min: salaryMin,
            salary_max: salaryMax,
            currency: currency,
            url: offer.url,
            publish_date: publishDate,
            content_hash: finalHash
        }
    });
}

return normalizedOffers;
